<?php
/** Administrator audience, personal messaging, and broadcast UI. @package Dhikra */
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class Dhikra_Audience_Admin {
	private const PAGE='dhikra-audience';
	public function register():void{add_action('admin_menu',array($this,'admin_menu'));add_action('admin_post_dhikra_audience_message',array($this,'send_message'));add_action('admin_post_dhikra_broadcast_create',array($this,'create_broadcast'));add_action('admin_post_dhikra_broadcast_cancel',array($this,'cancel_broadcast'));}
	public function admin_menu():void{add_submenu_page('edit.php?post_type=dhikra_telangor',__('مخاطبان ذکری','dhikra'),__('مخاطبان و پیام‌ها','dhikra'),'manage_dhikra_rewards',self::PAGE,array($this,'render_page'));}
	private function page_url(array $args=array()):string{$url=admin_url('edit.php?post_type=dhikra_telangor&page='.self::PAGE);return $args?add_query_arg($args,$url):$url;}
	private function authorize(string $nonce):void{if(!current_user_can('manage_dhikra_rewards')){wp_die(esc_html__('دسترسی ندارید.','dhikra'));}check_admin_referer($nonce);}
	public function create_broadcast():never{$this->authorize('dhikra_broadcast_create');$text=sanitize_textarea_field(wp_unslash($_POST['message']??''));$key=sanitize_key(wp_unslash($_POST['request_key']??''));$result=Dhikra_Broadcast::create($text,get_current_user_id(),$key);$args=is_wp_error($result)?array('dhikra_error'=>$result->get_error_message()):array('dhikra_notice'=>__('ارسال همگانی ساخته شد و در صف قرار گرفت.','dhikra'));wp_safe_redirect($this->page_url($args));exit;}
	public function cancel_broadcast():never{$this->authorize('dhikra_broadcast_cancel');$id=absint($_POST['broadcast_id']??0);$ok=Dhikra_Broadcast::cancel($id);wp_safe_redirect($this->page_url($ok?array('dhikra_notice'=>__('ارسال همگانی لغو شد؛ پیام‌های ارسال‌شده قابل بازگشت نیستند.','dhikra')):array('dhikra_error'=>__('این ارسال قابل لغو نیست.','dhikra'))));exit;}
	public function send_message():never{$this->authorize('dhikra_audience_message');$id=absint($_POST['audience_id']??0);$text=sanitize_textarea_field(wp_unslash($_POST['message']??''));global $wpdb;$table=Dhikra_Data::table('audience');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d",$id),ARRAY_A);if(!is_array($row)||''===trim($text)){wp_safe_redirect($this->page_url(array('dhikra_error'=>__('مخاطب یا متن پیام معتبر نیست.','dhikra'))));exit;}$result=Dhikra_Audience::send_logged_message($id,(string)$row['eitaa_user_id'],$text,'personal');if('sent'!==(string)$result['status']){wp_safe_redirect($this->page_url(array('dhikra_error'=>(string)($result['error']??__('ارسال پیام ناموفق بود و برای تلاش مجدد ثبت شد.','dhikra')))));exit;}$wpdb->update($table,array('last_message_at'=>current_time('mysql',true)),array('id'=>$id),array('%s'),array('%d'));wp_safe_redirect($this->page_url(array('dhikra_notice'=>__('پیام ارسال و در گزارش ثبت شد.','dhikra'))));exit;}
	public function render_page():void{
		if(!current_user_can('manage_dhikra_rewards')){return;}global $wpdb;$audience=Dhikra_Data::table('audience');$messages=Dhikra_Data::table('messages');$broadcasts=Dhikra_Data::table('broadcasts');
		$q=sanitize_text_field(wp_unslash($_GET['s']??''));$where='';$params=array();if(''!==$q){$like='%'.$wpdb->esc_like($q).'%';$where='WHERE eitaa_user_id LIKE %s OR first_name LIKE %s OR last_name LIKE %s';$params=array($like,$like,$like);}$sql="SELECT * FROM {$audience} {$where} ORDER BY last_seen_at DESC LIMIT 100";$rows=$params?$wpdb->get_results($wpdb->prepare($sql,...$params),ARRAY_A):$wpdb->get_results($sql,ARRAY_A);
		$stats=$wpdb->get_row("SELECT COUNT(*) total,SUM(allows_write_to_pm=1) eligible,SUM(allows_write_to_pm=0) skipped FROM {$audience}",ARRAY_A);$recent=$wpdb->get_results("SELECT * FROM {$broadcasts} ORDER BY id DESC LIMIT 20",ARRAY_A);$request_key=wp_generate_uuid4();
		?><div class="wrap dhikra-settings-wrap"><h1><?php esc_html_e('مخاطبان و پیام‌های ایتا','dhikra');?></h1><?php if(!empty($_GET['dhikra_notice'])):?><div class="notice notice-success"><p><?php echo esc_html(sanitize_text_field(wp_unslash($_GET['dhikra_notice'])));?></p></div><?php endif;if(!empty($_GET['dhikra_error'])):?><div class="notice notice-error"><p><?php echo esc_html(sanitize_text_field(wp_unslash($_GET['dhikra_error'])));?></p></div><?php endif;?>
		<div class="dhikra-settings-card dhikra-broadcast-card"><h2><?php esc_html_e('ارسال پیام همگانی','dhikra');?></h2><p><?php esc_html_e('پیام برای همه مخاطبانی که اجازه دریافت پیام از برنامک ایتا را دارند، از طریق صف ارسال خواهد شد.','dhikra');?></p><p class="description"><?php esc_html_e('ارسال پیام همگانی ممکن است از اعتبار ارسال پیام برنامک ایتا استفاده کند.','dhikra');?></p><div class="dhikra-broadcast-summary"><?php printf(esc_html__('این پیام برای %1$s نفر از %2$s مخاطب قابل ارسال است. %3$s نفر مجوز دریافت پیام ندارند.','dhikra'),esc_html(number_format_i18n(absint($stats['eligible']??0))),esc_html(number_format_i18n(absint($stats['total']??0))),esc_html(number_format_i18n(absint($stats['skipped']??0))));?></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" class="dhikra-broadcast-form" data-confirm="<?php echo esc_attr(sprintf(__('این پیام برای %s مخاطب دارای مجوز وارد صف می‌شود. ادامه می‌دهید؟','dhikra'),number_format_i18n(absint($stats['eligible']??0))));?>"><input type="hidden" name="action" value="dhikra_broadcast_create"><input type="hidden" name="request_key" value="<?php echo esc_attr($request_key);?>"><?php wp_nonce_field('dhikra_broadcast_create');?><textarea name="message" rows="7" maxlength="<?php echo esc_attr((string)Dhikra_Broadcast::MAX_LENGTH);?>" required placeholder="<?php esc_attr_e('متن پیام همگانی را بنویسید…','dhikra');?>"></textarea><div class="dhikra-broadcast-actions"><span class="description"><?php printf(esc_html__('حداکثر %s نویسه؛ متن ساده و چندخطی مجاز است.','dhikra'),esc_html(number_format_i18n(Dhikra_Broadcast::MAX_LENGTH)));?></span><button class="button button-primary dhikra-broadcast-submit" type="submit"><?php esc_html_e('ارسال برای همه','dhikra');?></button></div></form></div>
		<div class="dhikra-settings-card"><h2><?php esc_html_e('ارسال‌های همگانی اخیر','dhikra');?></h2><?php if(empty($recent)):?><p><?php esc_html_e('هنوز ارسال همگانی ثبت نشده است.','dhikra');?></p><?php else:?><div class="dhikra-broadcast-list"><?php foreach($recent as $b):$eligible=absint($b['eligible_count']);$done=absint($b['sent_count'])+absint($b['failed_count']);$pct=$eligible>0?min(100,(int)round(100*$done/$eligible)):100;$details=$wpdb->get_results($wpdb->prepare("SELECT m.status,m.attempts,m.last_error,m.sent_at,m.eitaa_user_id,a.first_name,a.last_name FROM {$messages} m LEFT JOIN {$audience} a ON a.id=m.audience_id WHERE m.broadcast_id=%d ORDER BY m.id DESC LIMIT 100",absint($b['id'])),ARRAY_A);?><article class="dhikra-broadcast-item"><div class="dhikra-broadcast-head"><strong><?php echo esc_html(wp_html_excerpt($b['message_text'],80,'…'));?></strong><span><?php echo esc_html($b['created_at']);?> — <?php echo esc_html($b['status']);?></span></div><p><?php printf(esc_html__('ارسال‌شده: %1$s / %2$s | ناموفق نهایی: %3$s | بدون مجوز: %4$s','dhikra'),esc_html(number_format_i18n(absint($b['sent_count']))),esc_html(number_format_i18n($eligible)),esc_html(number_format_i18n(absint($b['failed_count']))),esc_html(number_format_i18n(absint($b['skipped_no_permission']))));?></p><div class="dhikra-progress"><span style="width:<?php echo esc_attr((string)$pct);?>%"></span></div><small><?php echo esc_html(number_format_i18n($pct));?>٪</small><?php if(in_array($b['status'],array('queued','processing'),true)):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" onsubmit="return confirm('<?php echo esc_js(__('ارسال‌های انجام‌شده بازگردانده نمی‌شوند. ارسال را لغو می‌کنید؟','dhikra'));?>');"><input type="hidden" name="action" value="dhikra_broadcast_cancel"><input type="hidden" name="broadcast_id" value="<?php echo esc_attr((string)$b['id']);?>"><?php wp_nonce_field('dhikra_broadcast_cancel');?><button class="button button-link-delete"><?php esc_html_e('لغو ارسال','dhikra');?></button></form><?php endif;?><details><summary><?php esc_html_e('جزئیات گیرندگان','dhikra');?></summary><table class="widefat striped"><thead><tr><th>مخاطب</th><th>شناسه ایتا</th><th>وضعیت</th><th>تلاش</th><th>خطا / زمان ارسال</th></tr></thead><tbody><?php foreach($details as $d):?><tr><td><?php echo esc_html(trim($d['first_name'].' '.$d['last_name'])?:'—');?></td><td><code><?php echo esc_html($d['eitaa_user_id']);?></code></td><td><?php echo esc_html($d['status']);?></td><td><?php echo esc_html((string)absint($d['attempts']));?></td><td><?php echo esc_html($d['last_error']?:($d['sent_at']?:'—'));?></td></tr><?php endforeach;?></tbody></table></details></article><?php endforeach;?></div><?php endif;?></div>
		<form method="get"><input type="hidden" name="post_type" value="dhikra_telangor"><input type="hidden" name="page" value="<?php echo esc_attr(self::PAGE);?>"><p class="search-box"><input type="search" name="s" value="<?php echo esc_attr($q);?>"><button class="button"><?php esc_html_e('جستجو','dhikra');?></button></p></form><table class="widefat striped"><thead><tr><th>مخاطب</th><th>شناسه ایتا</th><th>آخرین ورود</th><th>مجوز پیام</th><th>تلنگر روزانه</th><th>پیام شخصی</th></tr></thead><tbody><?php foreach(is_array($rows)?$rows:array() as $row):?><tr><td><?php echo esc_html(trim($row['first_name'].' '.$row['last_name'])?:__('بدون نام','dhikra'));?></td><td><code><?php echo esc_html($row['eitaa_user_id']);?></code></td><td><?php echo esc_html($row['last_seen_at']);?></td><td><?php echo !empty($row['allows_write_to_pm'])?'✅':'—';?></td><td><?php echo !empty($row['daily_enabled'])?'✅':'—';?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="dhikra_audience_message"><input type="hidden" name="audience_id" value="<?php echo esc_attr((string)$row['id']);?>"><?php wp_nonce_field('dhikra_audience_message');?><textarea name="message" rows="2" required placeholder="متن پیام شخصی…"></textarea><button class="button button-primary">ارسال</button></form></td></tr><?php endforeach;?></tbody></table></div><?php
	}
}
